use serde_json::{Value, from_str};

pub fn solve(input: Value) -> Value {
    let (left, right): (Vec<(i64, i64)>, Vec<(i64, i64)>) = input.as_array()
        .expect("Input must be an array")
        .chunks(2)
        .map(|chunk| {
            let key = chunk[0].as_array().expect("Key must be an array")[0]
                .as_i64()
                .expect("Key must be an integer");
            let value = chunk[0].as_array().expect("Key must be an array")[1]
                .as_i64()
                .expect("Value must be an integer");
            (key, value)
        })
        .unzip();

    let mut result = Vec::new();
    let mut left_iter = left.into_iter().peekable();
    let mut right_iter = right.into_iter().peekable();

    while left_iter.peek().is_some() || right_iter.peek().is_some() {
        let (left_key, left_value) = left_iter.next().unwrap_or((0, 0));
        let (right_key, right_value) = right_iter.next().unwrap_or((0, 0));

        if left_key < right_key {
            if let Some(&(_, right_value)) = right_iter.peek() {
                right_iter.next();
                result.push((left_key, left_value, right_value));
            } else {
                result.push((left_key, left_value, 0));
            }
        } else if left_key > right_key {
            if let Some(&(_, left_value)) = left_iter.peek() {
                left_iter.next();
                result.push((right_key, 0, right_value));
            } else {
                result.push((right_key, 0, right_value));
            }
        } else {
            result.push((left_key, left_value, right_value));
        }
    }

    Value::Array(result.into_iter().map(|(k, l, r)| Value::Array(vec![Value::Number(k.into()), Value::Number(l.into()), Value::Number(r.into())])).collect())
}
